#pragma once
#include "gallery_cluster_input.hpp"
#include "../tests/cluster_visual_compare.hpp"
int run_gallery_cluster_gpu(bool warp,const std::filesystem::path& folder){std::filesystem::create_directories(folder);Experiment gpu(warp,800,800);gpu.cache_assets=true;TwoFramePipeline pipeline(gpu);SceneGpuSurfaces surfaces(gpu,pipeline);surfaces.native_paint=surfaces.retain_paint=true;unsigned captures{},cases{},inputs{};double worst{};std::ostringstream report;report<<"{\"format\":\"gallery-cluster-gpu-v1\",\"captures\":[";
    for(unsigned index=34;index<gallery_scene_count;++index){const auto d=gallery_scene_descriptors[index];GallerySceneSession session(d.group,d.index,d.width,d.height,"cluster-utilities.css");session.vm.eval(scene_read(CE_SOURCE_DIR "/examples/crpg-gallery/native/case-list.js"));const auto id=session.vm.eval("__ceGalleryCases["+std::to_string(d.catalog_index)+"].id");gallery_cluster_prepare(session,id);std::array<bool,gallery_scene_count> visible{};visible[index]=true;std::cout<<id<<" GPU..."<<std::flush;
        for(unsigned frame=0;frame<=300;++frame){session.step(frame*(1000./60));inputs+=gallery_cluster_inputs(session,frame);if(std::find(gallery_cluster_capture_frames.begin(),gallery_cluster_capture_frames.end(),frame)==gallery_cluster_capture_frames.end())continue;
            auto owned=std::make_shared<const caseelephant::ProbeSceneFrame>(session.current);for(unsigned version=0;version<3;++version){auto& surface=surfaces.paint_owned(index,owned,2);surfaces.publish();FramePacket packet;packet.draws.push_back({{0,0,float(surface.width),float(surface.height)},{1,1,1,1},0});const auto serial=pipeline.submit(std::move(packet),[]{},{},{surface.handle});surfaces.submitted(serial,visible);}
            const auto actual=surfaces.read(index),expected=scene_reference(std::filesystem::path(CE_SOURCE_DIR)/"tests/fixtures/gallery-cluster-reference"/(id+"-"+std::to_string(frame)+".png"));auto difference=scene_difference(actual,expected);const auto mean=*std::max_element(difference.mean.begin(),difference.mean.end());worst=std::max(worst,mean);std::vector<Pixel> pixels(std::size_t(actual.width)*actual.height);std::memcpy(pixels.data(),actual.rgba.data(),actual.rgba.size());save_png(folder/(id+"-"+std::to_string(frame)+".png"),pixels,actual.width,actual.height);if(captures++)report<<',';report<<"{\"id\":"<<json_string(id)<<",\"frame\":"<<frame<<",\"mean\":"<<mean<<",\"iou\":"<<difference.soft_iou<<'}';if(!cluster_image_match(actual,expected)){std::cerr<<id<<" frame "<<frame<<" mean "<<mean<<" IoU "<<difference.soft_iou<<'\n';throw std::runtime_error("GPU cluster original browser oracle");}
        }surfaces.retire_card(index);session.unmount();require(session.vm.stats().live_nodes==3,"cluster GPU owner leak");++cases;std::cout<<" OK\n";
    }surfaces.release();gpu.evict_assets(0,true);gpu.check_debug_messages();require(cases==30&&captures==210&&pipeline.submissions==pipeline.completions,"cluster GPU coverage/real retirement");report<<"],\"case_count\":"<<cases<<",\"input_count\":"<<inputs<<",\"max_mean\":"<<worst<<",\"submissions\":"<<pipeline.submissions<<",\"completions\":"<<pipeline.completions<<",\"native_passes\":"<<surfaces.native_work().passes<<",\"fallback_passes\":"<<surfaces.native_work().fallbacks<<",\"debug_warning_error_count\":"<<(gpu.debug_layer?"0":"null")<<'}';write_text(folder/"report.json",report.str());std::cout<<"PASS "<<cases<<" cases / "<<captures<<" browser images / "<<pipeline.completions<<" completed submissions\n";return 0;
}
